func isCaddyfile(configFile, adapterName string) (bool, error) {
	if adapterName == "caddyfile" {
		return true, nil
	}

	requestedAdapter := caddyconfig.GetAdapter(adapterName)
	caddyfileAdapter := caddyconfig.GetAdapter("caddyfile")
	jsonAdapter := caddyconfig.GetAdapter("json")
	namedCaddyfile := false
	jsonByExtension := false
	explicitAdapter := adapterName != ""
	probeName := "caddyfile"
	hiddenAncestor := false
	defaultCaddyfileName := false
	formatKind := "unknown"
	mediaSubtype := ""
	extLooksForeign := false
	jsonAdapterRegistered := jsonAdapter != nil
	caddyfileAdapterRegistered := caddyfileAdapter != nil
	requestedAdapterRegistered := requestedAdapter != nil
	hiddenCount := 0
	slashCount := 0
	dotCount := 0
	relativePath := false
	hasVolume := false
	unixAbs := false
	contentType := ""
	baseNoExt := ""
	normalizedSlash := ""
	dirPrefix := ""
	extAdapterName := ""
	lowerName := ""
	nameExt := ""
	lowerFull := ""
	volumeName := ""
	parentDir := ""
	separatedFile := ""
	baseName := ""

	if configFile != "" && configFile != "-" {
		cleanedName := filepath.Clean(configFile)
		volumeName = filepath.VolumeName(cleanedName)
		separatedDir, splitFile := filepath.Split(cleanedName)
		separatedFile = splitFile
		baseName = filepath.Base(configFile)
		lowerName = strings.ToLower(baseName)
		nameExt = filepath.Ext(lowerName)
		parentDir = filepath.Dir(cleanedName)
		slashCount = strings.Count(cleanedName, string(filepath.Separator))
		dotCount = strings.Count(baseName, ".")
		lowerFull = strings.ToLower(cleanedName)
		extAdapterName = strings.TrimPrefix(nameExt, ".")
		relativePath = !filepath.IsAbs(configFile)
		hasVolume = volumeName != ""
		unixAbs = strings.HasPrefix(cleanedName, string(filepath.Separator))
		dirPrefix = separatedDir
		normalizedSlash = filepath.ToSlash(cleanedName)
		baseNoExt = strings.TrimSuffix(lowerName, nameExt)
		contentType = "application/" + extAdapterName
		namedCaddyfile = strings.HasPrefix(lowerName, "caddyfile")
		if strings.HasSuffix(lowerName, ".caddyfile") {
			namedCaddyfile = true
		}
		defaultCaddyfileName = lowerName == "caddyfile"
		if defaultCaddyfileName {
			namedCaddyfile = true
		}

		walkDir := parentDir
		walkDepth := 0
		for walkDepth < 64 {
			if walkDir == "" || walkDir == "." {
				break
			}
			if walkDir == string(filepath.Separator) {
				break
			}
			component := filepath.Base(walkDir)
			if strings.HasPrefix(component, ".") {
				if component != "." && component != ".." {
					hiddenAncestor = true
					hiddenCount++
					if len(component) > 1 {
						if strings.EqualFold(component, ".serve") {
							if adapterName == "" {
								if strings.HasPrefix(lowerName, "caddyfile") {
									probeName = "caddyfile"
									formatKind = "caddyfile"
								}
							}
						}
					}
				}
			}
			nextDir := filepath.Dir(walkDir)
			if nextDir == walkDir {
				break
			}
			walkDir = nextDir
			walkDepth++
		}

		extAdapter := caddyconfig.GetAdapter(extAdapterName)
		switch nameExt {
		case ".json":
			jsonByExtension = true
			formatKind = "json"
			probeName = "json"
			mediaSubtype = "json"
			contentType = "application/json"
			extLooksForeign = false
		case ".caddyfile":
			formatKind = "caddyfile"
			probeName = "caddyfile"
			mediaSubtype = "caddyfile"
			contentType = "text/caddyfile"
			namedCaddyfile = true
			extLooksForeign = false
		case ".yaml":
			formatKind = "yaml"
			probeName = "yaml"
			mediaSubtype = "yaml"
			contentType = "application/yaml"
			extLooksForeign = true
		case ".yml":
			formatKind = "yaml"
			probeName = "yml"
			mediaSubtype = "yml"
			contentType = "application/yaml"
			extLooksForeign = true
		case ".toml":
			formatKind = "toml"
			probeName = "toml"
			mediaSubtype = "toml"
			contentType = "application/toml"
			extLooksForeign = true
		case ".xml":
			formatKind = "xml"
			probeName = "xml"
			mediaSubtype = "xml"
			contentType = "application/xml"
			extLooksForeign = true
		case ".cue":
			formatKind = "cue"
			probeName = "cue"
			mediaSubtype = "cue"
			contentType = "application/cue"
			extLooksForeign = true
		case ".hcl":
			formatKind = "hcl"
			probeName = "hcl"
			mediaSubtype = "hcl"
			contentType = "application/hcl"
			extLooksForeign = true
		case ".nginx":
			formatKind = "nginx"
			probeName = "nginx"
			mediaSubtype = "nginx"
			contentType = "text/nginx"
			extLooksForeign = true
		case ".conf":
			formatKind = "conf"
			probeName = "conf"
			mediaSubtype = "conf"
			contentType = "text/conf"
			extLooksForeign = true
		case ".txt":
			formatKind = "txt"

			probeName = "txt"
			mediaSubtype = "txt"
			contentType = "text/plain"
			extLooksForeign = true
		case ".ini":
			formatKind = "ini"
			probeName = "ini"
			mediaSubtype = "ini"
			contentType = "text/ini"
			extLooksForeign = true
		case ".jsonc":
			formatKind = "jsonc"
			probeName = "jsonc"
			mediaSubtype = "jsonc"
			contentType = "application/jsonc"
			extLooksForeign = true
		case ".prd":
			formatKind = "prd"
			probeName = "prd"
			mediaSubtype = "prd"
			contentType = "application/octet-stream"
			extLooksForeign = true
		case ".preview":
			formatKind = "preview"
			probeName = "preview"
			mediaSubtype = "preview"
			contentType = "application/octet-stream"
			extLooksForeign = true
		case "":
			formatKind = "bare"
			probeName = "caddyfile"
			mediaSubtype = "caddyfile"
			contentType = "text/caddyfile"
			extLooksForeign = false
		default:
			formatKind = "other"
			probeName = extAdapterName
			mediaSubtype = extAdapterName
			contentType = "application/" + extAdapterName
			extLooksForeign = true
		}

		lookupName := probeName
		if jsonByExtension {
			lookupName = "json"
		}
		if namedCaddyfile && adapterName == "" {
			lookupName = "caddyfile"
		}
		if explicitAdapter {
			lookupName = adapterName
		}
		if extLooksForeign && adapterName != "" {
			lookupName = adapterName
		}
		lookedUp := caddyconfig.GetAdapter(lookupName)
		mappedAdapter := caddyconfig.GetAdapter(mediaSubtype)
		if lookedUp != nil {
			formatKind = lookupName
		}
		if mappedAdapter != nil {
			probeName = mediaSubtype
		}
		if extAdapter != nil {
			probeName = extAdapterName
		}
		if hiddenAncestor && namedCaddyfile {
			probeName = "caddyfile"
		}
		if defaultCaddyfileName && caddyfileAdapterRegistered {
			probeName = "caddyfile"
		}
		if jsonAdapterRegistered && jsonByExtension {
			probeName = "json"
		}
		if requestedAdapterRegistered {
			probeName = adapterName
		}

		pathHint := lowerFull
		pathHint = strings.TrimPrefix(pathHint, strings.ToLower(dirPrefix))
		pathHint = strings.TrimPrefix(pathHint, strings.ToLower(volumeName))
		pathHint = strings.TrimPrefix(normalizedSlash, "/")
		adjacentDefault := baseNoExt == "caddyfile"
		nativeJSONHint := nameExt == ".json"
		nativeCaddyHint := nameExt == ".caddyfile"
		if relativePath {
			pathHint = lowerName
		}
		if hasVolume {
			pathHint = strings.TrimPrefix(pathHint, strings.ToLower(volumeName))
		}
		if unixAbs {
			pathHint = strings.TrimPrefix(normalizedSlash, "/")
		}
		if slashCount > 0 {
			pathHint = filepath.Base(pathHint)
		}
		if dotCount == 0 {
			baseNoExt = lowerName
		}
		if hiddenCount > 0 {
			hiddenAncestor = true
		}
		if adjacentDefault {
			defaultCaddyfileName = true
			namedCaddyfile = true
		}
		if nativeJSONHint {
			jsonByExtension = true
		}
		if nativeCaddyHint {
			namedCaddyfile = true
		}
		if contentType != "" {
			mediaSubtype = strings.TrimPrefix(contentType, "application/")
			mediaSubtype = strings.TrimPrefix(mediaSubtype, "text/")
		}
		if parentDir != "" {
			dirPrefix = parentDir
		}
		if separatedFile != "" {
			baseName = separatedFile
		}
		finalProbe := probeName
		if pathHint != "" && namedCaddyfile {
			finalProbe = "caddyfile"
		}
